/**
 * Simulated side-bet EV by true-count bucket (SPEC §5.3 `COUNT_EV_TABLE`), used by the Learn mode and the Coach.
 *
 * Generated by the derivation described in docs/COUNTING.md: 500,000 eight-deck EZ shoes (DEFAULT_RULES: cut card
 * 14 from the end, burn procedure on) dealt by the engine with seed 20261026 — 40,740,655 hands. Before every hand
 * the true count of each system (running count ÷ max(decks remaining, 0.5), from all face-up cards including the
 * exposed burn card) picked the bucket; the bet's return (+40 / +25 on a hit, −1 otherwise) was averaged per bucket.
 * Reproduce with `simulateCountEv` (src/strategy/countEv.ts) and the same seed.
 */
import type { CountEvRow } from './types';
import { DRAGON7_COUNT, PANDA8_COUNT } from './counting';

function row(tcMin: number, tcMax: number, hands: number, frequency: number, ev: number): CountEvRow {
  return Object.freeze({ tcMin, tcMax, hands, frequency, ev });
}

export const COUNT_EV_TABLE: Record<'dragon7' | 'panda8', CountEvRow[]> = Object.freeze({
  dragon7: Object.freeze([
    row(-Infinity, -2, 7929705, 0.194639, -0.181867),
    row(-2, 0, 11182050, 0.274469, -0.0975017),
    row(0, 2, 13239126, 0.324961, -0.0598643),
    row(2, 4, 4287022, 0.105227, -0.0258557),
    row(4, 6, 1884904, 0.0462659, 0.0248347),
    row(6, 8, 937028, 0.0229998, 0.0691185),
    row(8, 10, 524478, 0.0128736, 0.112636),
    row(10, 12, 305955, 0.00750982, 0.148035),
    row(12, Infinity, 450387, 0.011055, 0.22248),
  ]) as CountEvRow[],
  panda8: Object.freeze([
    row(-Infinity, -2, 10362006, 0.254341, -0.170929),
    row(-2, 0, 9139490, 0.224333, -0.112375),
    row(0, 2, 10775785, 0.264497, -0.0928241),
    row(2, 4, 4486940, 0.110134, -0.068797),
    row(4, 6, 2298901, 0.0564277, -0.0447784),
    row(6, 8, 1276675, 0.0313366, -0.0193244),
    row(8, 10, 781324, 0.019178, 0.0121153),
    row(10, 12, 496304, 0.012182, 0.0207131),
    row(12, Infinity, 1123230, 0.0275702, 0.0860358),
  ]) as CountEvRow[],
});

export interface CountEvAtThreshold {
  threshold: number;
  /** Share of hands on which the count says to bet. */
  frequency: number;
  /** Average EV per unit on those hands. */
  ev: number;
  /** Standard error of `ev` from the derivation run. */
  stdErr: number;
  /** Units won per 100 hands dealt, betting one unit on every qualifying hand. */
  unitsPer100Hands: number;
}

/** Provenance of COUNT_EV_TABLE and the pooled results at each system's threshold. */
export const COUNT_EV_META = Object.freeze({
  shoes: 500000,
  hands: 40740655,
  seed: 20261026,
  decks: 8,
  cutCardFromEnd: 14,
  burnProcedure: true,
  generatedOn: '2026-10-26',
  atThreshold: Object.freeze({
    dragon7: Object.freeze({ threshold: DRAGON7_COUNT.threshold, frequency: 0.1007, ev: 0.0771, stdErr: 0.0032, unitsPer100Hands: 0.776 }) as CountEvAtThreshold,
    panda8: Object.freeze({ threshold: PANDA8_COUNT.threshold, frequency: 0.0589, ev: 0.0485, stdErr: 0.0033, unitsPer100Hands: 0.286 }) as CountEvAtThreshold,
  }),
});

/**
 * Pooled frequency and EV of the table's rows at or above a true count (hands-weighted). `threshold` should be one
 * of the table's bucket edges (−2, 0, 2, …, 12); a value inside a bucket pools only the buckets fully above it.
 */
export function countEvFrom(bet: 'dragon7' | 'panda8', threshold: number): { frequency: number; ev: number; unitsPer100Hands: number } {
  let frequency = 0;
  let weighted = 0;
  for (const r of COUNT_EV_TABLE[bet]) {
    if (r.tcMin < threshold) continue;
    frequency += r.frequency;
    weighted += r.frequency * r.ev;
  }
  const ev = frequency === 0 ? 0 : weighted / frequency;
  return { frequency, ev, unitsPer100Hands: weighted * 100 };
}
